// The kernel is organized as a standard time loop around a spatial 5-point stencil.
// We optimize spatial traversal by:
//   * restricting to the interior once via a proto-structure
//   * applying 2D blocking (tiling) in both i and j using noarr::into_blocks
//   * hoisting block indices to the outermost position to improve cache reuse
//
// The actual index state seen inside the lambda is still expressed in terms of
// global 'i' and 'j' (thanks to traverser(order(...))), so neighbor access
// semantics remain identical to the original implementation.
[[gnu::flatten, gnu::noinline]]
void kernel_jacobi_2d(int tsteps, auto A, auto B) {
	using namespace noarr;

	// A, B: i x j, row-major (j is the fast dimension)
	auto n = A | get_length<'i'>();
	auto inner_len = n - 2; // number of interior points in each dimension

	// Tunable spatial tile sizes (in elements of the interior region).
	// These are compile-time constants that can be tuned for a specific cache
	// hierarchy or architecture.
	constexpr std::size_t BLOCK_I = 32; // tile height  (along rows, 'i')
	constexpr std::size_t BLOCK_J = 32; // tile width   (along cols, 'j')

	// Make sure the effective tile sizes do not exceed the interior size.
	auto effective_block_i = std::min<std::size_t>(BLOCK_I, inner_len);
	auto effective_block_j = std::min<std::size_t>(BLOCK_J, inner_len);

	// Compute block sizes that divide the interior length so that
	// no partial tiles appear and no into_blocks_dynamic/Static is needed.
	// This keeps the traversal simple and branch-free in the inner loops.
	auto gcd = [](std::size_t a, std::size_t b) {
		while (b != 0) {
			auto t = a % b;
			a = b;
			b = t;
		}
		return a;
	};

	auto block_i = gcd(inner_len, effective_block_i);
	auto block_j = gcd(inner_len, effective_block_j);

	// Handle degenerate cases: if inner_len == 0, gcd(inner_len, 0) == 0.
	// We fall back to a block size of 1, which results in a valid (but empty)
	// traversal once slicing is applied (slice length 0).
	if (block_i == 0) block_i = 1;
	if (block_j == 0) block_j = 1;

	// Proto-structure that:
	//   1. restricts traversal to the interior [1, n-2] x [1, n-2]
	//   2. applies 2D tiling in i and j:
	//        Dim 'i'  -> blocks 'I' (block row), inner 'i' (row within block)
	//        Dim 'j'  -> blocks 'J' (block col), inner 'j' (col within block)
	//   3. hoists block indices so that iteration order is:
	//        I (outer) -> J -> i -> j (innermost)
	//
	// Thanks to traverser(order(...)), the lambda still receives states in
	// terms of the original dimensions 'i' and 'j'. Block indices 'I' and 'J'
	// are used only to guide traversal order and are not exposed in the state.
	auto interior_block_order =
		slice<'i'>(1, inner_len) ^
		slice<'j'>(1, inner_len) ^
		into_blocks<'i', 'I', 'i'>(block_i) ^
		into_blocks<'j', 'J', 'j'>(block_j) ^
		// hoist J first, then I: final order is I, J, i, j
		hoist<'J'>() ^
		hoist<'I'>();

	// Pre-create unit index shifts along i and j to avoid re-constructing
	// these small states in the inner lambda body.
	const auto di = idx<'i'>(1);
	const auto dj = idx<'j'>(1);

#pragma scop
	for (int t = 0; t < tsteps; t++) {
		// First sweep: B := stencil(A)
		//
		// Traversal order:
		//   tiles in J within each I, then rows (i) and columns (j) inside the tile.
		// This preserves row-major access within each tile and improves cache reuse
		// compared to a purely linear i/j traversal over the whole domain.
		traverser(A, B)
			.order(interior_block_order)
			.for_each([&](auto state) {
				// state carries global interior indices (i,j) satisfying
				//   1 <= i <= n-2
				//   1 <= j <= n-2
				// so the 4-neighborhood is always within bounds.
				auto west  = state - dj;
				auto east  = state + dj;
				auto south = state + di;
				auto north = state - di;

				B[state] = (num_t)0.2 *
				           (A[state] + A[west] + A[east] + A[south] + A[north]);
			});

