#include "jacobi-2d.hpp"

using num_t = DATA_TYPE;

namespace {

// Logical dimensions:
//   'i' = row index (slow / outer in row-major)
//   'j' = column index (fast / inner in row-major)
constexpr auto i_vec = noarr::vector<'i'>();
constexpr auto j_vec = noarr::vector<'j'>();

// Tunable spatial blocking factors (both must be > 0).
// These determine the "tile" size in the i and j dimensions for the
// blocked Jacobi sweeps. They are chosen for a typical x64 machine,
// but can be freely adjusted to better suit a particular cache hierarchy.
constexpr std::size_t I_BLOCK = 32;
constexpr std::size_t J_BLOCK = 64;

struct tuning {
	// A and B are N x N with C-style row-major layout: i = row, j = column
	// Layout: scalar<num_t> ^ vector<'j'> ^ vector<'i'>
	// => 'j' is the innermost (contiguous) dimension.
	DEFINE_PROTO_STRUCT(a_layout, j_vec ^ i_vec);
	DEFINE_PROTO_STRUCT(b_layout, j_vec ^ i_vec);
} tuning;


// Array initialization
void init_array(auto A, auto B) {
	using namespace noarr;

	// Cache the length once, instead of querying it in every iteration.
	auto n = A | get_length<'i'>();

	// A, B: i x j
	traverser(A, B).for_each([=](auto state) {
		auto [i, j] = get_indices<'i', 'j'>(state);

		A[state] = ((num_t)i * (num_t)(j + 2) + (num_t)2) / (num_t)n;
		B[state] = ((num_t)i * (num_t)(j + 3) + (num_t)3) / (num_t)n;
	});
}


// One Jacobi sweep: dst := stencil(src) on the interior points 1..n-2 (both dims)
//
// This function is written once and used for both A->B and B->A passes.
// It implements a 2D blocked traversal over the interior, plus clean tail
// handling for domains whose interior is not exactly divisible by the block
// sizes. All spatial loops are expressed via Noarr traversers and orders.
template<typename SrcBag, typename DstBag>
inline void jacobi_sweep(const SrcBag &src, const DstBag &dst, std::size_t inner_len) {
	using namespace noarr;

	const num_t w = (num_t)0.2;

	// Number of interior points in each dimension is inner_len = n - 2.
	//
	// Compute the largest multiples of the tile sizes that fit into the interior.
	// These define the fully-tiled top-left sub-rectangle.
	const std::size_t full_i = (inner_len / I_BLOCK) * I_BLOCK;
	const std::size_t full_j = (inner_len / J_BLOCK) * J_BLOCK;

	// Common stencil application over an arbitrary traversal of the interior.
	// The traversal object is a Noarr traverser already configured with an
	// appropriate .order(...).for_each is then used to visit each interior point.
	auto apply_stencil = [&](auto traversal) {
		traversal.for_each([&](auto state) {
			// state contains indices for 'i' and 'j' (and possibly extra blocking
			// dimensions, which are ignored by the bags). We only manipulate 'i'
			// and 'j' here via state arithmetic on plain states (never on traversers).
			auto west  = state - idx<'j'>(1);
			auto east  = state + idx<'j'>(1);
			auto south = state + idx<'i'>(1);
			auto north = state - idx<'i'>(1);

			dst[state] = w * (src[state] + src[west] + src[east] + src[south] + src[north]);
		});
	};

	// If the interior is too small to contain at least one full 2D tile in both
	// directions, fall back to a simple (non-blocked) interior traversal.
	//
	// This keeps the code simple and avoids corner cases for very small grids
	// while preserving the original semantics.
	if (full_i == 0 || full_j == 0) {
		auto interior =
			noarr::slice<'i'>(1, inner_len) ^
			noarr::slice<'j'>(1, inner_len);

		apply_stencil(noarr::traverser(src).order(interior));
		return;
	}

	// 1) Fully tiled interior rectangle:
	//    i in [1, full_i], j in [1, full_j]
	//
	// We first restrict to this rectangle via slices, and then apply two
	// into_blocks transformations to get block indices 'I' and 'J' and
	// hoist them to the outermost positions. This yields a cache-friendly
	// traversal:
	//   for I (block rows)
	//     for J (block cols)
	//       for i inside tile
	//         for j inside tile (contiguous in memory)
	{
		auto tiled_order =
			noarr::slice<'i'>(1, full_i) ^
			noarr::slice<'j'>(1, full_j) ^
			// Split 'j' into blocks first (block index 'J', inner index 'j')
			(noarr::into_blocks<'j', 'J', 'j'>(noarr::lit<J_BLOCK>) ^ noarr::hoist<'J'>()) ^
			// Then split 'i' into blocks (block index 'I', inner index 'i')
			(noarr::into_blocks<'i', 'I', 'i'>(noarr::lit<I_BLOCK>) ^ noarr::hoist<'I'>());

		apply_stencil(noarr::traverser(src).order(tiled_order));
	}

	// 2) Right-hand vertical stripe (if any remaining columns):
	//    i in [1, full_i], j in [1 + full_j, inner_len]
	if (full_j < inner_len) {
		auto right_edge =
			noarr::slice<'i'>(1, full_i) ^
			noarr::slice<'j'>(1 + full_j, inner_len - full_j);

		apply_stencil(noarr::traverser(src).order(right_edge));
	}

	// 3) Bottom horizontal stripe (if any remaining rows):
	//    i in [1 + full_i, inner_len], j in [1, full_j]
	if (full_i < inner_len) {
		auto bottom_edge =
			noarr::slice<'i'>(1 + full_i, inner_len - full_i) ^
			noarr::slice<'j'>(1, full_j);

		apply_stencil(noarr::traverser(src).order(bottom_edge));
	}

	// 4) Bottom-right corner (if there are remaining rows and columns):
	//    i in [1 + full_i, inner_len], j in [1 + full_j, inner_len]
	if (full_i < inner_len && full_j < inner_len) {
		auto corner =
			noarr::slice<'i'>(1 + full_i, inner_len - full_i) ^
			noarr::slice<'j'>(1 + full_j, inner_len - full_j);

		apply_stencil(noarr::traverser(src).order(corner));
	}
}


// Main computational kernel
