		auto [i, j] = get_indices<'i', 'j'>(state);
		auto n = A | get_length<'i'>();

		A[state] = ((num_t)i * (num_t)(j + 2) + (num_t)2) / (num_t)n;
		B[state] = ((num_t)i * (num_t)(j + 3) + (num_t)3) / (num_t)n;
	});
}


// Main computational kernel
// - Two Jacobi sweeps per time step:
//     B := stencil(A);  A := stencil(B)
// - Data traversal is expressed purely with Noarr traversers.
// - We block the interior region along the i (row) dimension using
//   noarr::into_blocks_dynamic to improve cache behavior for large N.
[[gnu::flatten, gnu::noinline]]
void kernel_jacobi_2d(int tsteps, auto A, auto B) {
	using namespace noarr;

	// A, B: i x j
	auto n = A | get_length<'i'>();
	auto inner_len = n - 2; // number of interior points in each dimension

	// Degenerate case: no interior to update (N <= 2)
	if (inner_len == 0)
		return;

	// Constant Jacobi weight; kept outside loops so the compiler can
	// propagate it easily.
	constexpr num_t weight = (num_t)0.2;

	// Proto-structure describing just the interior region:
	//   i, j in [1, n-2]
	// States produced by traversers that use this "order" still carry
	// the original global indices 'i' and 'j' (1..n-2), as in the
	// original version. The slice only affects which indices are
	// visited, not what the indices are.
	auto interior =
		slice<'i'>(1, inner_len) ^
		slice<'j'>(1, inner_len);

	// Block the interior along the i (row) dimension:
	//   - 'i' (rows) is split into:
	//       'I' : block index in i
	//       'i' : index within the block
	//       'r' : presence dimension (0/1) for handling the last
	//             partial block if inner_len % block_i != 0
	//
	//   - We use into_blocks_dynamic so that *any* inner_len works,
	//     not only multiples of block_i.
	//
	//   - The additional dimensions 'I' and 'r' are internal to the
	//     traverser: states passed to the kernel lambda still only
	//     contain the original 'i' and 'j' indices. The only effect
	//     is the (more cache-friendly) iteration order:
	//       block-of-rows -> row-inside-block -> columns.
	auto blocked_i =
		interior ^
		into_blocks_dynamic<'i', 'I', 'i', 'r'>(tuning.block_i);

	// Pre-build traversers for the blocked interior of A and B.
	// These encapsulate the tiling strategy and can be reused for
	// each time step; they always see the current contents of A/B.
	auto travA = traverser(A).order(blocked_i);
	auto travB = traverser(B).order(blocked_i);

#pragma scop
	for (int t = 0; t < tsteps; t++) {
		// First sweep: B := stencil(A)
		travA.for_each([&](auto state) {
			// state has interior (i,j) in the original index space:
			//   1 <= i,j <= n-2
			// Neighbor states are obtained by simple index arithmetic.
			auto west  = state - idx<'j'>(1);
			auto east  = state + idx<'j'>(1);
			auto south = state + idx<'i'>(1);
			auto north = state - idx<'i'>(1);

			B[state] = weight * (A[state] + A[west] + A[east] + A[south] + A[north]);
		});

		// Second sweep: A := stencil(B)
		travB.for_each([&](auto state) {
			auto west  = state - idx<'j'>(1);
			auto east  = state + idx<'j'>(1);
			auto south = state + idx<'i'>(1);
			auto north = state - idx<'i'>(1);

			A[state] = weight * (B[state] + B[west] + B[east] + B[south] + B[north]);
		});
	}
#pragma endscop
}

} // namespace


int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// problem size
	std::size_t n = N;
	std::size_t tsteps = TSTEPS;

	// set lengths of dimensions
	auto set_lengths =
		noarr::set_length<'i'>(n) ^
		noarr::set_length<'j'>(n);

	// allocate data
	auto A = noarr::bag(noarr::scalar<num_t>() ^ tuning.a_layout ^ set_lengths);
	auto B = noarr::bag(noarr::scalar<num_t>() ^ tuning.b_layout ^ set_lengths);

	// initialize arrays
	init_array(A.get_ref(), B.get_ref());

	auto start = std::chrono::high_resolution_clock::now();

	// run kernel
	kernel_jacobi_2d((int)tsteps, A.get_ref(), B.get_ref());

	auto end = std::chrono::high_resolution_clock::now();

	auto duration = std::chrono::duration<long double>(end - start);

	// print results (to prevent dead-code elimination)
	if (argc > 0 && argv[0] != ""s) {
		std::cerr << std::fixed << std::setprecision(2);
		noarr::serialize_data(std::cerr, A.get_ref() ^ noarr::hoist<'i'>());
	}

	// print timing
	std::cout << std::fixed << std::setprecision(6);
	std::cout << duration.count() << std::endl;
}
