	// Pre-compute n once instead of inside the lambda
	auto n = A | get_length<'i'>();

	// A, B: i x j
	// Default traverser order for this layout is row-major (i outer, j inner),
	// which matches the intended C-style memory layout and gives good locality.
	traverser(A, B).for_each([=](auto state) {
		auto [i, j] = get_indices<'i', 'j'>(state);

		A[state] = ((num_t)i * (num_t)(j + 2) + (num_t)2) / (num_t)n;
		B[state] = ((num_t)i * (num_t)(j + 3) + (num_t)3) / (num_t)n;
	});
}


// Main computational kernel
//
// We keep the same numerical scheme:
//   For t = 0..tsteps-1
//     B := 5-point stencil applied to A on interior points
//     A := 5-point stencil applied to B on interior points
//
// Only interior points with indices i,j in [1, n-2] are updated; the boundary
// values are left untouched and are used as Dirichlet boundaries.
//
// Optimization overview:
// - Restrict traversal to interior points once, via a proto-structure `interior`.
// - Apply 2D blocking in both 'i' (rows) and 'j' (columns) using
//   `noarr::into_blocks_dynamic` so we do not require divisibility.
//   This improves cache locality by processing tiles that fit better in caches.
// - Use `noarr::hoist` to make block indices the outer loops and keep
//   element indices ('i' and 'j') as inner loops.
// - Use `for_dims<'r','s'>` (presence flags from `into_blocks_dynamic`) to
//   skip incomplete cells in the edge tiles safely and cheaply.
// - Precompute the stencil weight 0.2 into a constant `w`.
//
[[gnu::flatten, gnu::noinline]]
void kernel_jacobi_2d(int tsteps, auto A, auto B) {
	using namespace noarr;

	// A, B: i x j
	auto n = A | get_length<'i'>();
	auto inner_len = n - 2; // number of interior points in each dimension

	// No interior -> nothing to do
	if (inner_len <= 0 || tsteps <= 0)
		return;

	// Tiling parameters (can be tuned for the target machine).
	// These control the tile size in the i and j dimensions.
	constexpr std::size_t BLOCK_I = 32;
	constexpr std::size_t BLOCK_J = 32;

	// Proto-structure that restricts indices to the interior region:
	//   i in [1, n-2], j in [1, n-2]
	//
	// We express this as a composition of slices; this is then reused in both
	// sweeps and for both arrays.
	auto interior =
		noarr::slice<'i'>(1, inner_len) ^
		noarr::slice<'j'>(1, inner_len);

	// Blocked traversal order:
	//
	// We split both 'i' and 'j' into blocks using into_blocks_dynamic so we
	// don't require inner_len to be a multiple of the block sizes. The extra
	// presence dimensions 'r' and 's' are used to mask out out-of-domain
	// elements in partially filled edge tiles.
	//
	// The resulting (virtual) dimensions are:
	//   - 'I': block index in i
	//   - 'i': index within the i-block
	//   - 'J': block index in j
	//   - 'j': index within the j-block
	//   - 'r': presence flag for i (length 0 or 1, depending on I,i)
	//   - 's': presence flag for j (length 0 or 1, depending on J,j)
	//
	// Using .order() means that the *states* seen inside the lambdas are still
	// expressed only in the original dimensions 'i' and 'j'; the extra
	// dimensions are only used by the traverser to decide the traversal order.
	//
	auto blocked_order =
		interior
		^ noarr::into_blocks_dynamic<'i', 'I', 'i', 'r'>(noarr::lit<BLOCK_I>)
		^ noarr::into_blocks_dynamic<'j', 'J', 'j', 's'>(noarr::lit<BLOCK_J>)
		// Hoist block indices to the top so that we traverse tiles first,
		// then the elements inside each tile. This improves cache locality.
		^ noarr::hoist<'I'>()
		^ noarr::hoist<'J'>();

	const num_t w = (num_t)0.2;

#pragma scop
	for (int t = 0; t < tsteps; t++) {
		// First sweep: B := stencil(A)
		//
		// Traversal pattern:
		//   - Outer loops: blocks in i ('I') and j ('J') via hoist
		//   - Next: presence flags 'r' and 's' via for_dims (skip invalid cells)
		//   - Inner loops: original indices 'i' and 'j' inside each valid tile
		//
		// The states passed to the innermost lambda are *always* expressed in
		// the original 'i' and 'j' dimensions, so we can compute neighbors
		// using simple index_in<'i'>/'j' arithmetic exactly as in the original
		// kernel. Blocking only changes the traversal order, not the mapping
		// from (i,j) to memory.
		noarr::traverser(A)
			.order(blocked_order)
			.template for_dims<'r', 's'>([&](auto trav_rs) {
				// For each valid combination of presence flags, iterate all
				// (tiled) interior points covered by this (r,s) combination.
				trav_rs.for_each([&](auto state) {
					auto west  = state - noarr::idx<'j'>(1);
					auto east  = state + noarr::idx<'j'>(1);
					auto south = state + noarr::idx<'i'>(1);
					auto north = state - noarr::idx<'i'>(1);

					B[state] = w * (A[state] + A[west] + A[east] + A[south] + A[north]);
				});
			});

		// Second sweep: A := stencil(B), same traversal pattern, roles swapped
		noarr::traverser(B)
			.order(blocked_order)
			.template for_dims<'r', 's'>([&](auto trav_rs) {
				trav_rs.for_each([&](auto state) {
					auto west  = state - noarr::idx<'j'>(1);
					auto east  = state + noarr::idx<'j'>(1);
					auto south = state + noarr::idx<'i'>(1);
					auto north = state - noarr::idx<'i'>(1);

					A[state] = w * (B[state] + B[west] + B[east] + B[south] + B[north]);
				});
			});
	}
#pragma endscop
